const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Helper to evaluate ee.Objects
    const get = (eeObj) => new Promise((resolve, reject) => eeObj.evaluate(resolve, reject));

    // 1. Geometry & constants
    const center = ee.Geometry.Point([46.70, 49.13]); // Lake Elton approx center
    const geom = center.buffer(12000); // ~12 km radius to cover the lake
    const scale = 1000; // per instruction to avoid timeout
    const maxPixels = 1e9;

    // Water mask from JRC GSW occurrence with fallback thresholds
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
    async function buildWaterMask() {
      const thresholds = [50, 25, 10, 1];
      for (let t of thresholds) {
        const wm = gsw.gt(t).selfMask().clip(geom);
        const waterCount = await get(ee.Image.constant(1).updateMask(wm)
          .reduceRegion({reducer: ee.Reducer.count(), geometry: geom, scale: scale, maxPixels: maxPixels}).get('constant'));
        if (waterCount && waterCount > 0) {
          return {mask: wm.rename('water'), thr: t, waterCount: waterCount};
        }
      }
      return {mask: ee.Image(0).selfMask(), thr: null, waterCount: 0};
    }
    const waterInfo = await buildWaterMask();
    console.log(`Water mask: occurrence > ${waterInfo.thr}% | Water pixels: ${waterInfo.waterCount}`);
    if (!waterInfo.waterCount || waterInfo.waterCount === 0) {
      console.log('C2');
      return;
    }
    const waterMask = waterInfo.mask;

    // Landsat L2 SR cloud masking and scaling to reflectance
    function maskAndScaleL57(img) {
      const qa = img.select('QA_PIXEL');
      const dilated = qa.bitwiseAnd(1 << 1).neq(0);
      const cloud = qa.bitwiseAnd(1 << 3).neq(0);
      const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
      const mask = dilated.or(cloud).or(cloudShadow).not();
      const green = img.select('SR_B2').multiply(0.0000275).add(-0.2).rename('green');
      return green.updateMask(mask).copyProperties(img, ['system:time_start']);
    }

    function collectionForYear(year, startMonth, endMonth) {
      const start = ee.Date.fromYMD(year, startMonth, 1);
      const end = ee.Date.fromYMD(year, endMonth, 1).advance(1, 'month');
      const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterBounds(geom).filterDate(start, end).map(maskAndScaleL57);
      const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterBounds(geom).filterDate(start, end).map(maskAndScaleL57);
      return l5.merge(l7).select('green');
    }

    async function getBestCollection(year) {
      const windows = [
        {sm: 6, em: 9, label: 'Jun-Sep'},
        {sm: 4, em: 10, label: 'Apr-Oct'},
        {sm: 1, em: 12, label: 'All-Year'}
      ];
      for (const w of windows) {
        const col = collectionForYear(year, w.sm, w.em);
        const size = await get(col.size());
        if (size && size > 0) return {col, size, label: w.label};
      }
      return {col: null, size: 0, label: 'None'};
    }

    async function computeYearStats(year) {
      const best = await getBestCollection(year);
      if (!best.col) {
        return {year, status: 'C1', msg: `Year ${year}: 0 images`};
      }
      const composite = best.col.median().clip(geom).updateMask(waterMask);
      const reducers = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
      const red = composite.reduceRegion({
        reducer: reducers,
        geometry: geom,
        scale: scale,
        maxPixels: maxPixels,
        bestEffort: true
      });
      const mean = await get(red.get('green_mean'));
      const count = await get(red.get('green_count'));
      const waterCount = waterInfo.waterCount;
      const coveragePct = (count && waterCount) ? (100 * count / waterCount) : 0;
      return {
        year,
        status: 'OK',
        images: best.size,
        window: best.label,
        mean: mean,
        count: count || 0,
        waterCount,
        coveragePct
      };
    }

    const y1 = 2004;
    const y2 = 2009;
    const stats1 = await computeYearStats(y1);
    const stats2 = await computeYearStats(y2);

    // Handle C1
    if (stats1.status === 'C1' || stats2.status === 'C1') {
      if (stats1.status === 'C1') console.log(`2004 Images: 0`);
      if (stats2.status === 'C1') console.log(`2009 Images: 0`);
      console.log('C1');
      return;
    }

    // Handle C2 (no valid pixels after masking)
    if ((stats1.count === 0) || (stats2.count === 0)) {
      console.log(`2004: Images ${stats1.images} (${stats1.window}), ValidPix ${stats1.count}/${stats1.waterCount} (${stats1.coveragePct.toFixed(1)}%), Mean green SR: ${stats1.mean}`);
      console.log(`2009: Images ${stats2.images} (${stats2.window}), ValidPix ${stats2.count}/${stats2.waterCount} (${stats2.coveragePct.toFixed(1)}%), Mean green SR: ${stats2.mean}`);
      console.log('C2');
      return;
    }

    // Validate means
    function invalidMean(v) {
      return v === null || v === undefined || isNaN(v) || v < -0.05 || v > 1.0;
    }
    if (invalidMean(stats1.mean) || invalidMean(stats2.mean)) {
      console.log(`2004 Mean: ${stats1.mean}, 2009 Mean: ${stats2.mean}`);
      console.log('C3');
      return;
    }

    // Print concise stats
    console.log(`2004: Images ${stats1.images} (${stats1.window}), ValidPix ${stats1.count}/${stats1.waterCount} (${stats1.coveragePct.toFixed(1)}%), Mean green SR: ${stats1.mean.toFixed(4)}`);
    console.log(`2009: Images ${stats2.images} (${stats2.window}), ValidPix ${stats2.count}/${stats2.waterCount} (${stats2.coveragePct.toFixed(1)}%), Mean green SR: ${stats2.mean.toFixed(4)}`);
    const diff = stats2.mean - stats1.mean;
    console.log(`Diff (2009 - 2004): ${diff.toFixed(4)}`);

    // Final answer
    const tol = 0.002; // small tolerance
    if (diff > tol) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
